    faqs: [
      { question: 'Do you have a branch in Bahrain?', answer: 'No. Bahrain is supplied from our Dubai warehouse, by road across the causeway or by air, with the documents prepared before dispatch.' },
      { question: 'Why does road freight to Bahrain take longer than to Dammam?', answer: 'Because it transits Saudi Arabia. The consignment carries Saudi transit formalities as well as Bahraini import ones, and the causeway adds a queue that is hard to promise to the hour.' },
      { question: 'Can you deliver to Hidd and the Bahrain Logistics Zone?', answer: 'Yes, on DAP terms to the gate. Both sit inside the Manama–Muharraq belt and add no meaningful time to the inland leg.' },
      { question: 'Do the products need a GCC conformity mark?', answer: 'Regulated categories do. We confirm at quotation which lines on your list fall inside the regulated scope and which do not.' },
      { question: 'Can you supply to smelter and refinery specifications?', answer: 'Yes. Where a specification names a standard — ISO 18752, EN 856 4SP, NACE MR0175 — we quote against that standard and the certification travels with the goods.' },
      { question: 'What currency do you quote in?', answer: 'AED, against real stock. USD invoicing is routine, and BHD is available on request.' },
      { question: 'Do you crimp hose assemblies before dispatch?', answer: 'Yes. Assemblies are crimped and pressure-tested in Dubai and shipped as finished items, tagged with the hose, the fitting and the test date.' },
      { question: 'Is there a minimum order?', answer: 'No minimum on stock items. Consolidating a mixed order into one consignment keeps it under a single set of documents.' },
    ],
