    sectors: [
      { slug: 'oil-gas', name: 'Oil & Gas', description: 'Wellhead, hose and valve support for Western Desert and Gulf of Suez operations and the LNG trains.' },
      { slug: 'steel', name: 'Steel & Metals', description: 'High-force cylinders and servo valves for rolling mills and forging lines.' },
      { slug: 'construction', name: 'Construction', description: 'Excavator, crane and batching-plant hydraulics for the new capital and infrastructure contracts.' },
      { slug: 'marine', name: 'Marine & Offshore', description: 'Deck machinery, crane and terminal handling hydraulics for the canal ports and Alexandria.' },
      { slug: 'power', name: 'Power & Energy', description: 'Actuator and governor hydraulics for thermal plant and the Aswan hydropower complex.' },
      { slug: 'mining', name: 'Mining', description: 'Dust-rated, high-cycle components for phosphate, cement and gold operations.' },
    ],
    faqs: [
      { question: 'Do you have a branch in Egypt?', answer: 'No. Egypt is supplied from our Dubai warehouse by sea, with the registration and documents completed before the container loads.' },
      { question: 'What is an ACID number and who raises it?', answer: 'The advance cargo declaration number on the Nafeza platform. The importer raises it against the consignment, and we supply the details it needs. Shipping documents have to carry it at loading.' },
      { question: 'What happens if a container sails without it?', answer: 'It is refused rather than delayed. That is why the registration comes before the booking, not after it.' },
      { question: 'Why is Egypt faster than the rest of North Africa?', answer: 'Because Ain Sokhna is inside the Red Sea, so the consignment needs no canal transit. Alexandria and Damietta run through Suez and take five to seven days longer.' },
      { question: 'Can you deliver to the Western Desert fields?', answer: 'Yes, on DAP terms to the site gate. The inland leg from Cairo or Alexandria is quoted rather than estimated.' },
      { question: 'Can you supply to refinery and LNG specifications?', answer: 'Yes. API 6A, API 16C and NACE MR0175 rated items with material certificates, plus SS316L fittings for process service.' },
      { question: 'What currency do you quote in?', answer: 'USD. It keeps the customs valuation and the bank documentation consistent.' },
      { question: 'Do you crimp hose assemblies before dispatch?', answer: 'Yes. Assemblies are crimped and pressure-tested in Dubai and shipped as finished items, tagged with the hose, the fitting and the test date.' },
    ],
    compliance: {
      heading: 'Nothing loads without an ACID number',
      body: 'Egypt runs advance cargo information, and it is not a formality that can be caught up later. The importer raises an ACID number on the Nafeza platform against the specific consignment, the exporter has to be registered with GOEIC for the goods concerned, and the shipping documents have to carry the ACID number when the container is loaded. A container that sails without it is refused rather than delayed. Send the part list and the importer’s details at quotation and the registration runs while the order is picked.',
      documents: [
        { ref: 'ACID', name: 'Advance cargo declaration number, Nafeza platform', issuer: 'Importer, before loading', when: 'Before the container loads' },
        { ref: 'GOEIC', name: 'Exporter registration for the goods concerned', issuer: 'General Organization for Export and Import Control', when: 'Once, then per product scope' },
        { ref: 'COO', name: 'Certificate of Origin', issuer: 'Dubai Chamber attested', when: 'Before dispatch' },
        { ref: 'INV / PL', name: 'Invoice & packing list carrying the ACID number', issuer: 'Indus Hydraulics', when: 'On loading' },
        { ref: 'MTC', name: 'Material & test certificates', issuer: 'Mill, or our test bench', when: 'Where the order calls for them' },
      ],
    },
