    localName: 'الجمهورية الجزائرية',
    lede: 'Algeria is a bank-first lane. Most imports have to be paid by documentary credit, with the import file domiciled with the buyer’s bank before anything ships, so the quotation has to be accurate enough to open a letter of credit against. Freight is straightforward once that is done: sea from Jebel Ali through Suez to Algiers or Skikda in under a month, or air into Algiers in under a week.',
