    faqs: [
      { question: 'Do you have a branch in Niger?', answer: 'No. Niger is supplied from our Dubai warehouse through Cotonou or Lomé, or by air into Niamey when the schedule requires it.' },
      { question: 'Why is this the longest African lane?', answer: 'Because it combines a Cape-routed sea leg with a thousand kilometres of road from the coast, and Arlit adds another nine hundred beyond Niamey.' },
      { question: 'Cotonou or Lomé?', answer: 'Cotonou for most orders, since the corridor to Niamey is the established one. Lomé when Cotonou is congested.' },
      { question: 'Can you deliver to Arlit and the mining north?', answer: 'Yes, on DAP terms to the site gate. The leg beyond Niamey is long and is quoted rather than estimated.' },
      { question: 'Can you supply mining operations directly?', answer: 'Yes. Dust-rated valves, four-spiral hose, high-cycle cylinders and crusher-duty components, with material certificates where the contract calls for them.' },
      { question: 'Is air freight worth it?', answer: 'On this lane, more often than most — six to eight days against six to seven weeks. We quote both so the choice is yours to make on cost.' },
      { question: 'What currency do you quote in?', answer: 'USD. It keeps the valuation consistent across the transit country and the destination.' },
      { question: 'Is there a minimum order?', answer: 'No minimum on stock items, but this is the lane where consolidation saves the most — one consignment, one set of documents, one corridor movement.' },
    ],
